static void backtrack(char **res, int *size, char *cur, int len, int open, int close, int n) {
  if (len == n * 2) {
    cur[len] = '\0';
    res[*size] = strdup(cur);
    (*size)++;
    return;
  }
  if (open < n) {
    cur[len] = '(';
    backtrack(res, size, cur, len + 1, open + 1, close, n);
  }
  if (close < open) {
    cur[len] = ')';
    backtrack(res, size, cur, len + 1, open, close + 1, n);
  }
}

char **generateParenthesis(int n, int *returnSize) {
  char **res = (char **)malloc(sizeof(char *) * 20000);
  char *cur = (char *)malloc(n * 2 + 1);
  *returnSize = 0;
  backtrack(res, returnSize, cur, 0, 0, 0, n);
  free(cur);
  return res;
}

class Solution {
  void backtrack(vector<string> &res, string &cur, int open, int close, int n) {
    if ((int)cur.size() == n * 2) {
      res.push_back(cur);
      return;
    }
    if (open < n) {
      cur.push_back('(');
      backtrack(res, cur, open + 1, close, n);
      cur.pop_back();
    }
    if (close < open) {
      cur.push_back(')');
      backtrack(res, cur, open, close + 1, n);
      cur.pop_back();
    }
  }

public:
  vector<string> generateParenthesis(int n) {
    vector<string> res;
    string cur;
    backtrack(res, cur, 0, 0, n);
    return res;
  }
};

func generateParenthesis(n int) []string {
	var res []string
	var cur []byte
	var backtrack func(open, close int)
	backtrack = func(open, close int) {
		if len(cur) == n*2 {
			res = append(res, string(cur))
			return
		}
		if open < n {
			cur = append(cur, '(')
			backtrack(open+1, close)
			cur = cur[:len(cur)-1]
		}
		if close < open {
			cur = append(cur, ')')
			backtrack(open, close+1)
			cur = cur[:len(cur)-1]
		}
	}
	backtrack(0, 0)
	return res
}

class Solution {
  private void backtrack(List<String> res, StringBuilder cur, int open, int close, int n) {
    if (cur.length() == n * 2) {
      res.add(cur.toString());
      return;
    }
    if (open < n) {
      cur.append('(');
      backtrack(res, cur, open + 1, close, n);
      cur.deleteCharAt(cur.length() - 1);
    }
    if (close < open) {
      cur.append(')');
      backtrack(res, cur, open, close + 1, n);
      cur.deleteCharAt(cur.length() - 1);
    }
  }

  public List<String> generateParenthesis(int n) {
    List<String> res = new ArrayList<>();
    backtrack(res, new StringBuilder(), 0, 0, n);
    return res;
  }
}

class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        res = []
        cur = []

        def backtrack(open_: int, close: int):
            if len(cur) == n * 2:
                res.append("".join(cur))
                return
            if open_ < n:
                cur.append("(")
                backtrack(open_ + 1, close)
                cur.pop()
            if close < open_:
                cur.append(")")
                backtrack(open_, close + 1)
                cur.pop()

        backtrack(0, 0)
        return res

impl Solution {
  pub fn generate_parenthesis(n: i32) -> Vec<String> {
    fn backtrack(res: &mut Vec<String>, cur: &mut String, open: i32, close: i32, n: i32) {
      if cur.len() == (n * 2) as usize {
        res.push(cur.clone());
        return;
      }
      if open < n {
        cur.push('(');
        backtrack(res, cur, open + 1, close, n);
        cur.pop();
      }
      if close < open {
        cur.push(')');
        backtrack(res, cur, open, close + 1, n);
        cur.pop();
      }
    }
    let mut res = vec![];
    let mut cur = String::new();
    backtrack(&mut res, &mut cur, 0, 0, n);
    res
  }
}

const generateParenthesis = (n: number): string[] => {
  const res: string[] = [];
  const cur: string[] = [];
  const backtrack = (open: number, close: number) => {
    if (cur.length === n * 2) {
      res.push(cur.join(''));
      return;
    }
    if (open < n) {
      cur.push('(');
      backtrack(open + 1, close);
      cur.pop();
    }
    if (close < open) {
      cur.push(')');
      backtrack(open, close + 1);
      cur.pop();
    }
  };
  backtrack(0, 0);
  return res;
};
